sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* Reset margini e padding globali */
body, html {
  margin: 0;
  padding: 0;
}

/* Forza larghezza totale e rimuove padding/margini da contenitori genitori comuni nel portale */
.container,
.container-fluid,
.page-content,
.panel,
.sn-widget {
  padding-left: 0 !important;
  padding-right: 0 !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
  max-width: 100% !important;
  width: 100% !important;
  box-sizing: border-box;
}

/* Rimuove bordi e ombre dal panel dentro il widget */
.sn-widget.panel,
.sn-widget.panel .panel-body {
  border: none !important;
  box-shadow: none !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
}

/* Regole specifiche per il widget */
.sn-widget.user-card {
  border: none;
  border-radius: 0 !important;
  background: transparent !important;
}

.sn-widget.user-card .panel-body {
  padding: 12px 20px !important;
  margin: 0 !important;
  background: transparent !important;
  color: white;
}

.sn-widget.user-card .user-icon {
  color: white;
  margin-right: 15px;
  background: transparent !important;
}

.sn-widget.user-card .media-heading,
.sn-widget.user-card h4 {
  font-size: 18px;
  font-weight: 600;
  margin: 0 0 5px 0;
  color: white;
  background: transparent !important;
}

.sn-widget.user-card .lead {
  margin: 0;
  font-size: 16px;
  font-weight: 400;
  color: white;
  background: transparent !important;
}

.sn-widget.user-card .label {
  font-size: 13px;
  padding: 5px 10px;
  border-radius: 12px;
  background: transparent !important;
  color: white;
  border: none;
}

sp_widget.script:
(function() {
  data.showWidget = false;

  var user = gs.getUser();
  var utenteGR = new GlideRecord('x_1763019_furgonch_utente');
  utenteGR.addQuery('sys_id', user.getID());
  utenteGR.query();

  if (utenteGR.next() && utenteGR.getValue('ruolo_utente').toLowerCase() === 'operatore') {
    data.showWidget = true;

    data.nome = utenteGR.getDisplayValue('first_name');
    data.cognome = utenteGR.getDisplayValue('last_name');
    data.ruolo = utenteGR.getDisplayValue('ruolo_utente'); 
    data.sottoruolo = utenteGR.getDisplayValue('sottoruolo_operatore'); 
  }
})();
